# DEBUG AREA 0 (SUBSPACE)
@token    = debug-area-0
@name     = DEBUG Area 0
@level    = 80
@size     = 50 x 16
@sheet    = mmrpg-overworld-2k25
#---------------------------#
@portals[]  = spawn(10-6, hidden)
@portals[]  = goto__debug-area-1(10-6, 6-23)
#---------------------------#
@field       = prototype-subspace
#---------------------------#
@pickups      = space-shard(60),shadow-shard(40),empty-shard(20),super-pellet(10),super-capsule(5),attack-booster(1),defense-booster(1),speed-booster(1),extra-life(1),yashichi(1)
