@terrain[]   = darkness(genesis-tower)
@terrain[]   = subspace(prototype-subspace)
@terrain[]   = water(reflection-chamber)
#---------------------------#
@habitats[] = dark-frag(darkness)
@habitats[] = trille-bot(subspace)
@habitats[] = novamite(water)
@habitats[] = mega-man-ds(subspace)
@habitats[] = bass-ds(subspace)
@habitats[] = proto-man-ds(subspace)
#---------------------------#
@items[]     = slur-module-1(47-8, chrono-circuit)
@items[]     = slur-module-2(47-9, cosmo-circuit)
@items[]     = slur-omega-seed(47-7, omega-seed)
